    "desc_th": "การฝึกปฏิบัติงานวิชาชีพด้านเภสัชกรรมชุมชนในร้านยาที่ได้รับการรับรองมาตรฐาน GPP ครอบคลุมการตรวจสอบและจ่ายยาตามใบสั่งแพทย์ตามหลักความปลอดภัยทางยา การให้คำปรึกษา   ด้านยาเชิงโครงสร้างแก่ผู้ป่วยกลุ่มทั่วไปและกลุ่มพิเศษ การคัดกรองและการจัดการโรคเบื้องต้น (Minor Ailment Triage) ด้วยแนวทางมาตรฐาน การจ่ายยาตามอาการและการส่งต่อผู้ป่วยที่มีสัญญาณอันตราย (Red Flags) อย่างเหมาะสม การให้คำแนะนำผลิตภัณฑ์สุขภาพเชิงพาณิชย์และสมุนไพรบนฐานหลักฐานเชิงประจักษ์ การบริหารจัดการร้านยา การประยุกต์ใช้เทคโนโลยีดิจิทัล ตลอดจนการพัฒนาทักษะ         การสื่อสารเชิงวิชาชีพและการบริบาลที่ยึดผู้ป่วยเป็นศูนย์กลางตามกรอบกฎหมาย จรรยาบรรณวิชาชีพ และมาตรฐานการคุ้มครองผู้บริโภค",
