    "question": "ทำไมราชวิทยาลัยจุฬาภรณ์จึงต้องเปิดคณะเภสัชศาสตร์และหลักสูตรเภสัชศาสตรบัณฑิตในเวลานี้ มีความซ้ำซ้อนกับมหาวิทยาลัยอื่นหรือไม่?",
    "answer": "<p><strong>ไม่ซ้ำซ้อนและมีความจำเป็นเร่งด่วนใน ๓ ประเด็นยุทธศาสตร์:</strong></p><ol><li><strong>การเติมเต็มช่องว่างด้านนวัตกรรมขั้นสูงของประเทศ:</strong> หลักสูตรเภสัชศาสตร์ในปัจจุบันส่วนใหญ่เน้นยาเคมีดั้งเดิม แต่หลักสูตร รจภ มุ่งเน้นเฉพาะด้าน <strong>ยาชีววัตถุ วัคซีน และ ATMPs (Cell & Gene Therapy)</strong> รวมถึง <strong>เภสัชศาสตร์แม่นยำ (Precision Pharmacy)</strong> ซึ่งเป็นอุตสาหกรรมเป้าหมายใหม่ (New S-Curve) ที่ประเทศขาดแคลนกำลังคนอย่างวิกฤต</li><li><strong>ตอบสนองพระปณิธานและจุดแข็งของ รจภ:</strong> สนับสนุนการบริบาลผู้ป่วยโรคมะเร็งและโรคซับซ้อนของโรงพยาบาลจุฬาภรณ์ และศูนย์ไซโคลตรอนและเพทสแกนแห่งชาติ ซึ่งต้องการเภสัชกรรังสี (Radiopharmacist) และผู้เชี่ยวชาญชีวบำบัด</li><li><strong>แก้ปัญหากำลังคนขาดแคลนในระบบ:</strong> ข้อมูลสภาเภสัชกรรมระบุว่าประเทศไทยยังมีเภสัชกรในระบบบริการจริงเพียง ๒๔,๐๐๐ คน ขาดแคลนกว่า ๑๐,๐๐๐ คนจากเป้าหมาย ๓๔,๐๐๐ คน</li></ol>"
