    "question": "จำนวนหน่วยกิต ๑๙๕ หน่วยกิต สอดคล้องกับเกณฑ์มาตรฐานของกระทรวง อว. และสภาเภสัชกรรมหรือไม่?",
    "answer": "<p><strong>สอดคล้องถูกต้องครบถ้วนตามกฎหมายและเกณฑ์มาตรฐานทุกประการ:</strong></p><ul><li>เกณฑ์มาตรฐานหลักสูตรปริญญาตรี พ.ศ. ๒๕๖๕ (อว.) กำหนดหลักสูตร ๖ ปี ไม่น้อยกว่า ๑๘๐ หน่วยกิต</li><li>ประกาศสภาเภสัชกรรม ที่ ๒๘/๒๕๖๘ และ ๖๕/๒๕๖๑ กำหนดไม่น้อยกว่า ๑๙๕ หน่วยกิต</li><li><strong>หลักสูตร รจภ จัดไว้ที่ ๑๙๕ หน่วยกิต พอดี:</strong><ul><li>หมวดวิชาศึกษาทั่วไป: <strong>๒๔ หน่วยกิต</strong> (๑๒.๓%)</li><li>หมวดวิชาเฉพาะ: <strong>๑๖๕ หน่วยกิต</strong> (๘๔.๖%) [แบ่งเป็น พื้นฐานวิชาชีพ ๒๗, วิชาชีพ ๘๙, ฝึกงานภาคบังคับ ๖, วิชาสาขาเน้น ๑๕, ฝึกงานสาขาเน้น ๒๘]</li><li>หมวดวิชาเลือกเสรี: <strong>๖ หน่วยกิต</strong> (๓.๑%)</li></ul></li><li>กระจายภาระการเรียนเฉลี่ยภาคเรียนละ ๑๖ - ๒๐ หน่วยกิต ไม่เกินเกณฑ์ข้อบังคับของราชวิทยาลัย</li></ul>"
