// App State
let currentTab = 'tab-chat';
let selectedYear = '1';
let selectedTrack = 'care';
let currentCouncilFilter = 'all';
let currentCourseGroupFilter = 'all';
let activeCourseModal = null;
let geminiApiKey = localStorage.getItem('cra_gemini_api_key') || '';
let geminiModel = localStorage.getItem('cra_gemini_model') || 'gemini-1.5-flash';

// Pre-computed Search Index for instant keyword retrieval
const SEARCH_INDEX = buildSearchIndex();

document.addEventListener('DOMContentLoaded', () => {
  initNavigation();
  initChat();
  initCouncilQA();
  initStudyPlan();
  initCoursesCatalog();
  initPLOs();
  initFaculty();
  initConfigModal();
});

// 1. Navigation Tabs
function initNavigation() {
  const tabs = document.querySelectorAll('.nav-tab');
  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      tabs.forEach(t => t.classList.remove('active'));
      document.querySelectorAll('.tab-pane').forEach(p => p.classList.remove('active'));
      
      tab.classList.add('active');
      const targetId = tab.getAttribute('data-tab');
      const targetPane = document.getElementById(targetId);
      if (targetPane) {
        targetPane.classList.add('active');
        currentTab = targetId;
      }
    });
  });
}

// 2. Chat Assistant System
function initChat() {
  const form = document.getElementById('chat-form');
  const input = document.getElementById('chat-input');
  const clearBtn = document.getElementById('btn-clear-chat');
  const chips = document.querySelectorAll('.chip-btn');

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const query = input.value.trim();
    if (!query) return;
    input.value = '';
    handleUserMessage(query);
  });

  clearBtn.addEventListener('click', () => {
    const container = document.getElementById('chat-messages');
    container.innerHTML = `
      <div class="chat-bubble bot-bubble">
        <div class="bubble-avatar"><i class="fa-solid fa-robot"></i></div>
        <div class="bubble-content">
          <div class="bubble-name">PharmD CRA Assistant</div>
          <div class="bubble-text">
            <p>ล้างประวัติการสนทนาเรียบร้อยครับ! มีประเด็นใดในหลักสูตรเภสัชศาสตรบัณฑิตที่ต้องการสอบถามเพิ่มเติมไหมครับ?</p>
          </div>
          <div class="bubble-time">เมื่อสักครู่</div>
        </div>
      </div>
    `;
  });

  chips.forEach(chip => {
    chip.addEventListener('click', () => {
      const query = chip.getAttribute('data-query');
      if (query) {
        // switch to chat tab if not active
        document.querySelector('[data-tab="tab-chat"]').click();
        handleUserMessage(query);
      }
    });
  });
}

function appendMessage(sender, text, isMarkdown = false) {
  const container = document.getElementById('chat-messages');
  const bubble = document.createElement('div');
  bubble.className = `chat-bubble ${sender === 'user' ? 'user-bubble' : 'bot-bubble'}`;

  const timeStr = new Date().toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit' });
  const avatarIcon = sender === 'user' ? 'fa-user' : 'fa-robot';
  const nameStr = sender === 'user' ? 'ท่าน (ผู้สอบถาม)' : 'PharmD CRA Assistant';

  bubble.innerHTML = `
    <div class="bubble-avatar"><i class="fa-solid ${avatarIcon}"></i></div>
    <div class="bubble-content">
      <div class="bubble-name">${nameStr}</div>
      <div class="bubble-text">${text}</div>
      <div class="bubble-time">${timeStr}</div>
    </div>
  `;

  container.appendChild(bubble);
  container.scrollTop = container.scrollHeight;
}

function showTypingIndicator() {
  const container = document.getElementById('chat-messages');
  const indicator = document.createElement('div');
  indicator.id = 'typing-indicator-node';
  indicator.className = 'chat-bubble bot-bubble';
  indicator.innerHTML = `
    <div class="bubble-avatar"><i class="fa-solid fa-robot"></i></div>
    <div class="bubble-content">
      <div class="typing-indicator">
        <div class="typing-dot"></div>
        <div class="typing-dot"></div>
        <div class="typing-dot"></div>
      </div>
    </div>
  `;
  container.appendChild(indicator);
  container.scrollTop = container.scrollHeight;
}

function removeTypingIndicator() {
  const node = document.getElementById('typing-indicator-node');
  if (node) node.remove();
}

async function handleUserMessage(query) {
  appendMessage('user', escapeHtml(query));
  showTypingIndicator();

  // If Gemini API Key exists, try calling live API, otherwise use high-speed built-in knowledge retrieval
  if (geminiApiKey) {
    try {
      const liveAnswer = await callGeminiAPI(query);
      removeTypingIndicator();
      appendMessage('bot', liveAnswer);
      return;
    } catch (err) {
      console.warn('Gemini API call failed, falling back to built-in knowledge base:', err);
    }
  }

  // Built-in intelligent answering engine
  setTimeout(() => {
    removeTypingIndicator();
    const answer = generateLocalAnswer(query);
    appendMessage('bot', answer);
  }, 450);
}

function generateLocalAnswer(query) {
  const qLower = query.toLowerCase();

  // 1. Check direct matches in Council QA
  for (const item of COUNCIL_QA) {
    const qText = item.question.toLowerCase();
    const keywords = ['ทำไม', 'ซ้ำซ้อน', 'atmp', 'หน่วยกิต', '๑๙๕', '195', 'ฝึกงาน', '๒,๐๐๐', '2000', 'ชั่วโมง', '๕ ท่าน', '5 ท่าน', 'อาจารย์ผู้รับผิดชอบ', 'มหิดล', 'พี่เลี้ยง', 'รพ.จุฬาภรณ์', 'ไซโคลตรอน', 'ai', 'ปัญญาประดิษฐ์', 'รับนักศึกษา', 'แผน ๗ ปี', 'สำเร็จการศึกษา', 'ใบอนุญาต'];
    
    // Check keyword intersection
    let matchScore = 0;
    keywords.forEach(kw => {
      if (qLower.includes(kw) && qText.includes(kw)) matchScore += 2;
    });

    if (matchScore >= 4 || qLower.includes(qText.substring(0, 15))) {
      return `
        <div class="qa-badge"><i class="fa-solid fa-certificate"></i> ข้อมูลตามเล่มหลักสูตร รจภ.</div>
        <p><strong>คำถาม:</strong> ${item.question}</p>
        <div style="margin-top: 8px;">${item.answer}</div>
      `;
    }
  }

  // 2. Specific domain searches
  if (qLower.includes('จุดเด่น') || qLower.includes('อัตลักษณ์') || qLower.includes('แตกต่าง')) {
    return `
      <div class="qa-badge"><i class="fa-solid fa-star"></i> จุดเด่น & อัตลักษณ์สำคัญของหลักสูตร</div>
      <p>หลักสูตรเภสัชศาสตรบัณฑิต ราชวิทยาลัยจุฬาภรณ์ มี <strong>๔ มิติแห่งความเป็นเลิศ</strong> ที่โดดเด่นและแตกต่างจากสถาบันอื่น ดังนี้:</p>
      <ul>
        <li><strong>๑. ยาชีววัตถุ วัคซีน และ ATMPs:</strong> มุ่งเน้นศาสตร์ผลิตภัณฑ์การแพทย์ขั้นสูง (Advanced Therapy Medicinal Products) ทั้งเซลล์บำบัด ยีนบำบัด (CAR-T Cells) และ Stem Cells ซึ่งเป็นกลุ่มยาอนาคตมูลค่าสูงตามยุทธศาสตร์ New S-Curve ของประเทศ</li>
        <li><strong>๒. เภสัชศาสตร์แม่นยำ (Precision Pharmacy):</strong> บูรณาการเภสัชพันธุศาสตร์ (Pharmacogenomics) เพื่อการวางแผนการรักษาและการใช้ยาเฉพาะบุคคล (Personalized Healthcare)</li>
        <li><strong>๓. บูรณาการ AI และ Big Data:</strong> มีรายวิชาจริยธรรม AI ใน Healthcare (<code>จภภศ๐๐๐๒</code>) และวิทยาการข้อมูลประยุกต์ด้านยา (<code>จภภศ๔๒๑๒</code>) เพื่อสร้างเภสัชกรแห่งยุคดิจิทัล</li>
        <li><strong>๔. ความเชี่ยวชาญด้านโรคมะเร็งและเภสัชภัณฑ์รังสี:</strong> ต่อยอดจากศักยภาพศูนย์ความเป็นเลิศด้านมะเร็ง โรงพยาบาลจุฬาภรณ์ และศูนย์ไซโคลตรอนและเพทสแกนแห่งชาติ</li>
      </ul>
      <p><em>หลักสูตรกำหนดหน่วยกิตรวมไม่น้อยกว่า ๑๙๕ หน่วยกิต โดยมีคณะเภสัชศาสตร์ มหาวิทยาลัยมหิดล เป็นสถาบันพี่เลี้ยง</em></p>
    `;
  }

  if (qLower.includes('หน่วยกิต') || qLower.includes('โครงสร้าง') || qLower.includes('หมวดวิชา')) {
    return `
      <div class="qa-badge"><i class="fa-solid fa-layer-group"></i> โครงสร้างหลักสูตร ๑๙๕ หน่วยกิต</div>
      <p>โครงสร้างหลักสูตรกำหนดหน่วยกิตรวม <strong>ไม่น้อยกว่า ๑๙๕ หน่วยกิต</strong> แบ่งออกเป็น ๓ หมวดวิชาหลัก ตามเกณฑ์ อว. และสภาเภสัชกรรม:</p>
      <ol>
        <li><strong>หมวดวิชาศึกษาทั่วไป:</strong> ๒๔ หน่วยกิต (วิชาบังคับและเลือกทางดิจิทัล จริยธรรม AI ภาษา และสุขภาวะ)</li>
        <li><strong>หมวดวิชาเฉพาะ:</strong> ๑๖๕ หน่วยกิต
          <ul>
            <li>วิชาพื้นฐานวิชาชีพ: ๒๗ หน่วยกิต</li>
            <li>วิชาชีพ: ๘๙ หน่วยกิต</li>
            <li>วิชาฝึกปฏิบัติงานวิชาชีพภาคบังคับ: ๖ หน่วยกิต (๓๐๐ ชม. ในปีที่ ๕ เทอม ๒)</li>
            <li>วิชาสาขาเน้น: ๑๕ หน่วยกิต (เลือกสายบริบาล หรือสายอุตสาหการ)</li>
            <li>วิชาฝึกปฏิบัติงานวิชาชีพสาขาเน้น: ๒๘ หน่วยกิต (๑,๗๐๐ ชม. ในปีที่ ๖ ทั้งปี)</li>
          </ul>
        </li>
        <li><strong>หมวดวิชาเลือกเสรี:</strong> ๖ หน่วยกิต</li>
      </ol>
      <p><em>รวมชั่วโมงฝึกปฏิบัติงานตลอดหลักสูตร ๒,๐๐๐ ชั่วโมงครบถ้วนตามเกณฑ์สภาเภสัชกรรม</em></p>
    `;
  }

  if (qLower.includes('atmp') || qLower.includes('ชีววัตถุ') || qLower.includes('วัคซีน') || qLower.includes('ยีน')) {
    return `
      <div class="qa-badge"><i class="fa-solid fa-vial-virus"></i> รายวิชาด้าน ATMPs และชีวเภสัชภัณฑ์</div>
      <p>หลักสูตรจัดกระบวนการเรียนรู้ด้านชีววัตถุและ ATMPs อย่างเข้มข้นผ่านรายวิชาสำคัญ ได้แก่:</p>
      <ul>
        <li><code>จภภศ๔๒๐๙</code> <strong>ชีววัตถุ วัคซีน และ ATMPs (๔ หน่วยกิต):</strong> ศึกษาการผลิตและเทคโนโลยีชีวเภสัชภัณฑ์, Upstream/Downstream process, CAR-T, Gene editing</li>
        <li><code>จภภศ๔๒๑๐</code> <strong>การกำกับดูแลผลิตภัณฑ์ยาและชีววัตถุ (๓ หน่วยกิต):</strong> กฎหมาย GMP/GDP, CTD, การขอขึ้นทะเบียนยากับ อย. และมาตรฐานสากล (US FDA, EMA)</li>
        <li><code>จภภศ๔๒๑๑</code> <strong>เซลล์ต้นกำเนิด วิศวกรรมเนื้อเยื่อ และการแพทย์ฟื้นฟู (๒ หน่วยกิต):</strong> Regenerative Medicine และ Tissue Engineering</li>
        <li><code>จภภศ๕๖๐๒</code> <strong>การผลิตและระบบคุณภาพยาชีววัตถุ (๒ หน่วยกิต):</strong> Cleanroom technology, Sterility assurance และ Biosafety</li>
      </ul>
      <p>บัณฑิตจึงพร้อมปฏิบัติงานได้ทั้งในศูนย์ผลิตยาชีววัตถุ, อย., โรงพยาบาลระดับตติยภูมิ, และบริษัทวิจัยระดับโลก</p>
    `;
  }

  if (qLower.includes('อาจารย์') || qLower.includes('ผู้รับผิดชอบ') || qLower.includes('คณาจารย์')) {
    return `
      <div class="qa-badge"><i class="fa-solid fa-user-doctor"></i> คณาจารย์ผู้รับผิดชอบหลักสูตร ๕ ท่าน</div>
      <p>หลักสูตรมีอาจารย์ผู้รับผิดชอบหลักสูตรที่มีคุณวุฒิตรงตามเกณฑ์ สป.อว. และสภาเภสัชกรรม ดังนี้:</p>
      <ol>
        <li><strong>รศ.ดร. จุฑามณี สุทธิสีสังข์</strong> (ปร.ด. เภสัชวิทยา ม.มหิดล) - ผู้เชี่ยวชาญด้านเภสัชวิทยา ระบบประสาทและหลอดเลือดสมอง นโยบายยาและระบบสุขภาพ</li>
        <li><strong>ศ.ดร. เภสัชกร ไพบูลย์ จึงสุวดี</strong> (Ph.D. in Pharmacy, University of Vienna) - ผู้เชี่ยวชาญด้านเภสัชบำบัดโรคมะเร็ง, CAR-T Cell Immunotherapy, Precision Pharmacy</li>
        <li><strong>รศ.ดร. เภสัชกรหญิง นริศา คำแก่น</strong> (Ph.D. in Biomedical Sciences, วุฒิบัตร อ.ภ. เภสัชกรรมสมุนไพร) - ผู้เชี่ยวชาญยาสมุนไพรและพฤกษบำบัด, นิติเภสัชศาสตร์</li>
        <li><strong>อ.ดร. เภสัชกรหญิง พิรุณรัตน์ เดชบำรุง</strong> (Ph.D. in Chemistry Nanoscience & Tech, CAS จีน) - ผู้เชี่ยวชาญนาโนเทคโนโลยีทางการแพทย์, ระบบนำส่งอนุภาคไขมัน (LNPs)</li>
        <li><strong>อ.ดร. เภสัชกรหญิง ปัฐวิกา เลิศปฏิภานพงษ์</strong> (Ph.D. in Veterinary Biomedical Sciences, Seoul National Univ.) - ผู้เชี่ยวชาญเภสัชวิทยาโมเลกุล การวิจัยมะเร็ง และการบริบาลเภสัชกรรม</li>
      </ol>
    `;
  }

  if (qLower.includes('ฝึกงาน') || qLower.includes('2000') || qLower.includes('๒,๐๐๐') || qLower.includes('ชั่วโมง')) {
    return `
      <div class="qa-badge"><i class="fa-solid fa-clock-rotate-left"></i> การฝึกปฏิบัติงานวิชาชีพ ๒,๐๐๐ ชั่วโมง</div>
      <p>การฝึกปฏิบัติงานวิชาชีพตลอดหลักสูตร ๖ ปี ได้รับการออกแบบให้สอดคล้องกับประกาศสภาเภสัชกรรม ที่ ๖๕/๒๕๖๑ ครบถ้วน ๒,๐๐๐ ชั่วโมง ดังนี้:</p>
      <ul>
        <li><strong>๑. ชั้นปีที่ ๕ ภาคเรียนที่ ๒ (๓๐๐ ชั่วโมง / ๖ หน่วยกิต):</strong>
          <ul>
            <li>ฝึกงานในโรงพยาบาล (<code>จภภศ๕๕๐๔</code>) ๑๕๐ ชม.</li>
            <li>ฝึกงานในร้านยาชุมชน (<code>จภภศ๕๕๐๕</code>) ๑๕๐ ชม.</li>
          </ul>
        </li>
        <li><strong>๒. ชั้นปีที่ ๖ ทั้งปีการศึกษา (๑,๗๐๐ ชั่วโมง / ๒๘ หน่วยกิต):</strong>
          <ul>
            <li>แบ่งการฝึกออกเป็น <strong>๗ ผลัด (Rotation)</strong> ผลัดละไม่น้อยกว่า ๒๔๐-๒๕๐ ชั่วโมง (๖ สัปดาห์ต่อผลัด)</li>
            <li>ฝึกในแหล่งฝึกมาตรฐาน เช่น โรงพยาบาลจุฬาภรณ์, ศูนย์ความเป็นเลิศด้านมะเร็ง, โรงงานผลิตยาชีววัตถุ, องค์การเภสัชกรรม, สถาบันวิจัยจุฬาภรณ์, และบริษัทชีวเภสัชภัณฑ์</li>
          </ul>
        </li>
      </ul>
      <p><em>นักศึกษาทุกคนต้องได้รับผลการประเมินระดับ S (Satisfactory) ในทุกรายวิชาฝึกงานเพื่อสำเร็จการศึกษา</em></p>
    `;
  }

  // 3. Search in Course Catalog
  const matchedCourses = COURSES_CATALOG.filter(c => 
    c.code_th.toLowerCase().includes(qLower) || 
    c.code_en.toLowerCase().includes(qLower) ||
    c.name_th.toLowerCase().includes(qLower) ||
    c.name_en.toLowerCase().includes(qLower) ||
    (c.desc_th && c.desc_th.toLowerCase().includes(qLower))
  );

  if (matchedCourses.length > 0) {
    const topCourse = matchedCourses[0];
    let html = `
      <div class="qa-badge"><i class="fa-solid fa-book-medical"></i> พบข้อมูลรายวิชาในหลักสูตร</div>
      <p><strong>${topCourse.code_th} (${topCourse.code_en}): ${topCourse.name_th}</strong></p>
      <p style="font-size:12px; color:#38bdf8; margin-top:-4px;"><em>${topCourse.name_en}</em></p>
      <p><strong>จำนวนหน่วยกิต:</strong> ${topCourse.credit} | <strong>วิชาบังคับก่อน:</strong> ${topCourse.prereq_th || 'ไม่มี'}</p>
      <p style="margin-top:6px; font-size:13px;"><strong>คำอธิบายรายวิชา:</strong> ${topCourse.desc_th}</p>
    `;
    if (matchedCourses.length > 1) {
      html += `<p style="margin-top:10px; font-size:12px; color:#94a3b8;">นอกจากนี้ยังพบรายวิชาที่เกี่ยวข้องอีก ${matchedCourses.length - 1} วิชา (เช่น ${matchedCourses.slice(1, 4).map(c => c.code_th + ' ' + c.name_th).join(', ')}) ท่านสามารถค้นหาเพิ่มเติมในแท็บ 'คลังรายวิชา' ได้ครับ</p>`;
    }
    return html;
  }

  // Fallback intelligent summary
  return `
    <div class="qa-badge"><i class="fa-solid fa-circle-info"></i> สรุปข้อมูลหลักสูตรเภสัชศาสตรบัณฑิต รจภ.</div>
    <p>เกี่ยวกับประเด็น <strong>"${escapeHtml(query)}"</strong>:</p>
    <p>หลักสูตรเภสัชศาสตรบัณฑิต (หลักสูตร ๖ ปี) (หลักสูตรใหม่ พ.ศ. ๒๕๗๑) โครงการจัดตั้งคณะเภสัชศาสตร์ ราชวิทยาลัยจุฬาภรณ์ มีจุดเน้นสำคัญในการผลิตเภสัชกรที่มีความเชี่ยวชาญด้าน <strong>ยาชีววัตถุ วัคซีน ATMPs เภสัชศาสตร์แม่นยำ และการแพทย์เฉพาะบุคคล</strong> โดยมีจำนวนหน่วยกิตรวม ๑๙๕ หน่วยกิต และมีคณะเภสัชศาสตร์ มหาวิทยาลัยมหิดล เป็นสถาบันพี่เลี้ยง</p>
    <p>หากท่านต้องการข้อมูลเฉพาะเจาะจง สามารถคลิกเลือกหัวข้อคำถามด่วนทางซ้ายมือ หรือเข้าชมแท็บ <strong>"แผนการศึกษา ๖ ปี"</strong>, <strong>"คลังรายวิชา"</strong> หรือ <strong>"เตรียมเสนอสภาฯ"</strong> ได้ทันทีครับ</p>
  `;
}

// 3. Council Q&A Accordion
function initCouncilQA() {
  renderCouncilQA('all');

  const filterBtns = document.querySelectorAll('.filter-btn');
  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      filterBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const cat = btn.getAttribute('data-council-cat');
      currentCouncilFilter = cat;
      renderCouncilQA(cat);
    });
  });
}

function renderCouncilQA(category) {
  const container = document.getElementById('council-accordion');
  const filtered = category === 'all' 
    ? COUNCIL_QA 
    : COUNCIL_QA.filter(item => item.category === category);

  container.innerHTML = filtered.map((item, idx) => `
    <div class="council-item" data-id="${item.id}">
      <div class="council-question" onclick="toggleCouncilItem(this)">
        <div class="q-left">
          <div class="q-number">${item.id}</div>
          <div class="q-text">${item.question}</div>
        </div>
        <div class="q-arrow"><i class="fa-solid fa-chevron-down"></i></div>
      </div>
      <div class="council-answer">
        ${item.answer}
      </div>
    </div>
  `).join('');
}

window.toggleCouncilItem = function(elem) {
  const parent = elem.closest('.council-item');
  const isOpen = parent.classList.contains('open');
  // close others if needed or keep multiple open
  parent.classList.toggle('open');
};

// 4. Study Plan View
function initStudyPlan() {
  renderStudyPlan('1', 'care');

  const yearBtns = document.querySelectorAll('.year-btn');
  yearBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      yearBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      selectedYear = btn.getAttribute('data-year');
      renderStudyPlan(selectedYear, selectedTrack);
    });
  });

  const trackBtns = document.querySelectorAll('.track-btn');
  trackBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      trackBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      selectedTrack = btn.getAttribute('data-track');
      renderStudyPlan(selectedYear, selectedTrack);
    });
  });
}

function renderStudyPlan(yearNum, track) {
  const container = document.getElementById('study-plan-display');
  const planData = CURRICULUM_DATA.study_plan;

  // Year Thai mapping
  const thDigits = { '1': '๑', '2': '๒', '3': '๓', '4': '๔', '5': '๕', '6': '๖' };
  const targetYearStr = `ปีที่ ${thDigits[yearNum] || yearNum}`;

  // Get courses matching target year
  let yearCourses = planData.filter(p => p.year && p.year.includes(targetYearStr));

  // If no courses matched directly by string, filter by course code digit
  if (yearCourses.length === 0) {
    yearCourses = planData.filter(p => {
      if (yearNum === '1') return p.code.includes('๐') || p.code.includes('๑');
      if (yearNum === '2') return p.code.includes('๒');
      if (yearNum === '3') return p.code.includes('๓');
      if (yearNum === '4') return p.code.includes('๔');
      if (yearNum === '5') return p.code.includes('๕');
      if (yearNum === '6') return p.code.includes('๖');
      return false;
    });
  }

  // Filter track for Year 5 & 6
  if (yearNum === '5') {
    if (track === 'care') {
      yearCourses = yearCourses.filter(c => !c.code.includes('๕๖๐๑') && !c.code.includes('๕๖๐๒') && !c.code.includes('๕๖๐๓') && !c.code.includes('๕๖๐๔') && !c.code.includes('๕๖๐๕'));
    } else {
      yearCourses = yearCourses.filter(c => !c.code.includes('๕๗๐๑') && !c.code.includes('๕๗๐๒') && !c.code.includes('๕๗๐๓') && !c.code.includes('๕๗๐๔') && !c.code.includes('๕๗๐๕'));
    }
  } else if (yearNum === '6') {
    if (track === 'care') {
      yearCourses = COURSES_CATALOG.filter(c => c.code_th.startsWith('จภภศ๖๙')).map(c => ({
        year: 'ปีที่ ๖',
        sem: 'ตลอดปีการศึกษา',
        code: c.code_th,
        name_th: c.name_th,
        credit: c.credit
      }));
    } else {
      yearCourses = COURSES_CATALOG.filter(c => c.code_th.startsWith('จภภศ๖๘')).map(c => ({
        year: 'ปีที่ ๖',
        sem: 'ตลอดปีการศึกษา',
        code: c.code_th,
        name_th: c.name_th,
        credit: c.credit
      }));
    }
  }

  // Group by semester
  const sem1 = yearCourses.filter(c => !c.sem || c.sem.includes('๑') || c.sem.includes('1'));
  const sem2 = yearCourses.filter(c => c.sem && (c.sem.includes('๒') || c.sem.includes('2')));

  // Render cards
  if (yearNum === '6') {
    container.innerHTML = `
      <div class="sem-card" style="grid-column: 1 / -1;">
        <div class="sem-header">
          <div class="sem-title"><i class="fa-solid fa-hospital-user text-gold"></i> การฝึกปฏิบัติงานวิชาชีพสาขาเน้น (${track === 'care' ? 'ด้านการบริบาลทางเภสัชกรรม' : 'ด้านเภสัชกรรมอุตสาหการ'})</div>
          <div class="sem-credits">๒๘ หน่วยกิต (๑,๗๐๐ ชั่วโมง) • ๗ ผลัด</div>
        </div>
        <p style="font-size:13px; color:#94a3b8; margin-bottom:14px;">นักศึกษาจะฝึกงานในแหล่งฝึกมาตรฐานสากล ผลัดละ ๖ สัปดาห์ (๒๔๐-๒๕๐ ชม.) ณ โรงพยาบาลจุฬาภรณ์, โรงพยาบาลศูนย์/ทั่วไป, และแหล่งผลิตยาชีววัตถุ:</p>
        <div class="courses-list-col">
          ${yearCourses.map(c => `
            <div class="course-item-row" onclick="openCourseModalByCode('${c.code}')">
              <span class="c-code">${c.code}</span>
              <span class="c-name">${c.name_th}</span>
              <span class="c-credit">${c.credit}</span>
            </div>
          `).join('')}
        </div>
      </div>
    `;
    return;
  }

  container.innerHTML = `
    <div class="sem-card">
      <div class="sem-header">
        <div class="sem-title"><i class="fa-solid fa-book-open text-cyan"></i> ภาคการศึกษาที่ ๑</div>
        <div class="sem-credits">${sem1.length} รายวิชา</div>
      </div>
      <div class="courses-list-col">
        ${sem1.length > 0 ? sem1.map(c => `
          <div class="course-item-row" onclick="openCourseModalByCode('${c.code}')">
            <span class="c-code">${c.code}</span>
            <span class="c-name">${c.name_th}</span>
            <span class="c-credit">${c.credit}</span>
          </div>
        `).join('') : '<p style="font-size:13px; color:#64748b;">ไม่มีรายวิชาในภาคเรียนนี้</p>'}
      </div>
    </div>

    <div class="sem-card">
      <div class="sem-header">
        <div class="sem-title"><i class="fa-solid fa-book-open text-cyan"></i> ภาคการศึกษาที่ ๒</div>
        <div class="sem-credits">${sem2.length} รายวิชา</div>
      </div>
      <div class="courses-list-col">
        ${sem2.length > 0 ? sem2.map(c => `
          <div class="course-item-row" onclick="openCourseModalByCode('${c.code}')">
            <span class="c-code">${c.code}</span>
            <span class="c-name">${c.name_th}</span>
            <span class="c-credit">${c.credit}</span>
          </div>
        `).join('') : '<p style="font-size:13px; color:#64748b;">ไม่มีรายวิชาในภาคเรียนนี้</p>'}
      </div>
    </div>
  `;
}

// 5. Courses Catalog & Live Search
function initCoursesCatalog() {
  renderCoursesGrid(COURSES_CATALOG);

  const searchInput = document.getElementById('course-search-input');
  const clearBtn = document.getElementById('btn-clear-search');
  const groupBtns = document.querySelectorAll('.group-btn');

  searchInput.addEventListener('input', () => {
    const val = searchInput.value.trim();
    clearBtn.style.display = val ? 'block' : 'none';
    filterAndRenderCourses();
  });

  clearBtn.addEventListener('click', () => {
    searchInput.value = '';
    clearBtn.style.display = 'none';
    filterAndRenderCourses();
  });

  groupBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      groupBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentCourseGroupFilter = btn.getAttribute('data-group');
      filterAndRenderCourses();
    });
  });

  // Close course modal
  const modalClose = document.getElementById('btn-close-modal');
  const modalBackdrop = document.getElementById('course-modal');
  modalClose.addEventListener('click', () => modalBackdrop.classList.remove('active'));
  modalBackdrop.addEventListener('click', (e) => {
    if (e.target === modalBackdrop) modalBackdrop.classList.remove('active');
  });
}

function filterAndRenderCourses() {
  const query = document.getElementById('course-search-input').value.trim().toLowerCase();
  let filtered = COURSES_CATALOG;

  // Filter by group
  if (currentCourseGroupFilter === 'gened') {
    filtered = filtered.filter(c => c.code_th.startsWith('จภภศ๐'));
  } else if (currentCourseGroupFilter === 'basic') {
    filtered = filtered.filter(c => c.code_th.startsWith('จภภศ๑') || c.code_th.startsWith('จภภศ๒๑'));
  } else if (currentCourseGroupFilter === 'indus') {
    filtered = filtered.filter(c => c.code_th.startsWith('จภภศ๒๒') || c.code_th.startsWith('จภภศ๓๒') || c.code_th.startsWith('จภภศ๔๒') || c.code_th.startsWith('จภภศ๕๖'));
  } else if (currentCourseGroupFilter === 'care') {
    filtered = filtered.filter(c => c.code_th.startsWith('จภภศ๒๓') || c.code_th.startsWith('จภภศ๓๓') || c.code_th.startsWith('จภภศ๔๓') || c.code_th.startsWith('จภภศ๕๗'));
  } else if (currentCourseGroupFilter === 'practice') {
    filtered = filtered.filter(c => c.code_th.startsWith('จภภศ๕๕') || c.code_th.startsWith('จภภศ๖๘') || c.code_th.startsWith('จภภศ๖๙'));
  }

  // Filter by query
  if (query) {
    filtered = filtered.filter(c => 
      c.code_th.toLowerCase().includes(query) ||
      c.code_en.toLowerCase().includes(query) ||
      c.name_th.toLowerCase().includes(query) ||
      c.name_en.toLowerCase().includes(query) ||
      (c.desc_th && c.desc_th.toLowerCase().includes(query)) ||
      (c.desc_en && c.desc_en.toLowerCase().includes(query))
    );
  }

  renderCoursesGrid(filtered);
}

function renderCoursesGrid(courses) {
  const grid = document.getElementById('courses-grid');
  const countNum = document.getElementById('courses-count-num');
  countNum.textContent = courses.length;

  if (courses.length === 0) {
    grid.innerHTML = `
      <div style="grid-column: 1 / -1; text-align: center; padding: 40px; color: #94a3b8;">
        <i class="fa-solid fa-magnifying-glass" style="font-size: 32px; margin-bottom: 12px; color: #64748b;"></i>
        <p>ไม่พบรายวิชาที่ตรงกับเงื่อนไขการค้นหา</p>
      </div>
    `;
    return;
  }

  grid.innerHTML = courses.map(c => `
    <div class="course-card" onclick="openCourseModalByCode('${c.code_th}')">
      <div class="course-card-top">
        <div class="course-header-row">
          <span class="badge-code">${c.code_th}</span>
          <span class="badge-credit">${c.credit}</span>
        </div>
        <h3>${c.name_th}</h3>
        <div class="en-title">${c.name_en}</div>
        <div class="snippet">${c.desc_th || 'คลิกเพื่อดูรายละเอียดเพิ่มเติม...'}</div>
      </div>
      <div class="course-card-bottom">
        <span class="prereq-tag">วิชาบังคับก่อน: ${c.prereq_th || 'ไม่มี'}</span>
        <span class="view-detail-btn">ดูคำอธิบาย <i class="fa-solid fa-arrow-right"></i></span>
      </div>
    </div>
  `).join('');
}

window.openCourseModalByCode = function(code) {
  const course = COURSES_CATALOG.find(c => c.code_th === code || c.code_en === code || code.includes(c.code_th));
  if (!course) return;

  const modalBody = document.getElementById('modal-content');
  modalBody.innerHTML = `
    <div class="modal-course-header">
      <div class="modal-course-codes">
        <span class="badge-code" style="font-size:14px; padding:4px 10px;">${course.code_th}</span>
        <span class="badge-code" style="background:rgba(255,255,255,0.08); color:#cbd5e1;">${course.code_en}</span>
        <span class="badge-credit" style="font-size:13px; margin-left:auto;">${course.credit}</span>
      </div>
      <div class="modal-title-th">${course.name_th}</div>
      <div class="modal-title-en">${course.name_en}</div>
    </div>

    <div class="modal-detail-block">
      <div class="modal-label"><i class="fa-solid fa-link"></i> วิชาบังคับก่อน (Prerequisite)</div>
      <p style="font-size:13.5px; color:#e2e8f0;">${course.prereq_th || 'ไม่มี'} (English: ${course.prereq_en || 'None'})</p>
    </div>

    <div class="modal-detail-block">
      <div class="modal-label"><i class="fa-solid fa-align-left"></i> คำอธิบายรายวิชา (ภาษาไทย)</div>
      <div class="modal-desc-box">${course.desc_th || 'ไม่มีข้อมูลคำอธิบายรายวิชา'}</div>
    </div>

    <div class="modal-detail-block">
      <div class="modal-label"><i class="fa-solid fa-globe"></i> Course Description (English)</div>
      <div class="modal-desc-box" style="font-style:italic;">${course.desc_en || 'No description available'}</div>
    </div>
  `;

  document.getElementById('course-modal').classList.add('active');
};

// 6. PLOs List
function initPLOs() {
  const container = document.getElementById('plos-container');
  const plos = CURRICULUM_DATA.plos;

  container.innerHTML = plos.map(plo => {
    let tagClass = 'tag-k';
    if (plo.ksec.includes('Skill') || plo.ksec.includes('ทักษะ')) tagClass = 'tag-s';
    if (plo.ksec.includes('Ethic') || plo.ksec.includes('จริยธรรม')) tagClass = 'tag-e';
    if (plo.ksec.includes('Character') || plo.ksec.includes('ลักษณะ')) tagClass = 'tag-c';

    return `
      <div class="plo-card">
        <div class="plo-badge-col">
          <span class="plo-id">${plo.th_code}</span>
          <span class="plo-domain">${plo.domain}</span>
        </div>
        <div class="plo-desc-col">
          <span class="plo-ksec-tag ${tagClass}">${plo.ksec}</span>
          <div class="plo-desc-text">${plo.desc}</div>
        </div>
      </div>
    `;
  }).join('');
}

// 7. Faculty Members
function initFaculty() {
  const grid = document.getElementById('faculty-grid');
  const faculty = CURRICULUM_DATA.faculty;

  grid.innerHTML = faculty.map(f => {
    const edu = f.education || (f.degrees ? f.degrees.join('<br>') : '');
    const coursesStr = Array.isArray(f.courses) 
      ? f.courses.slice(0, 3).join(', ') + (f.courses.length > 3 ? ` และอื่นๆ รวม ${f.courses.length} วิชา` : '')
      : (f.courses || '');
    return `
      <div class="faculty-card">
        <div class="fac-top">
          <div class="fac-avatar"><i class="fa-solid fa-user-doctor"></i></div>
          <div>
            <div class="fac-name">${f.name} <span style="color:#d97706; font-size:16px;">★</span></div>
            <div class="fac-role">${f.role}</div>
          </div>
        </div>

        <div class="fac-section">
          <div class="fac-label"><i class="fa-solid fa-graduation-cap"></i> คุณวุฒิการศึกษา:</div>
          <div class="fac-val">${edu}</div>
        </div>

        <div class="fac-section">
          <div class="fac-label"><i class="fa-solid fa-chalkboard-user"></i> ภาระงานสอน (${f.courses_count || (f.courses ? f.courses.length : 0)} วิชา):</div>
          <div class="fac-val">${coursesStr}</div>
        </div>
      </div>
    `;
  }).join('');
}

// 8. Gemini API Configuration Modal & Live Call
function initConfigModal() {
  const btnConfig = document.getElementById('btn-api-config');
  const modal = document.getElementById('config-modal');
  const btnClose = document.getElementById('btn-close-config');
  const btnSave = document.getElementById('btn-save-key');
  const btnClear = document.getElementById('btn-clear-key');
  const inputKey = document.getElementById('gemini-key-input');
  const selectModel = document.getElementById('gemini-model-select');

  if (geminiApiKey) inputKey.value = geminiApiKey;
  if (geminiModel) selectModel.value = geminiModel;

  btnConfig.addEventListener('click', () => modal.classList.add('active'));
  btnClose.addEventListener('click', () => modal.classList.remove('active'));
  modal.addEventListener('click', (e) => {
    if (e.target === modal) modal.classList.remove('active');
  });

  btnSave.addEventListener('click', () => {
    geminiApiKey = inputKey.value.trim();
    geminiModel = selectModel.value;
    localStorage.setItem('cra_gemini_api_key', geminiApiKey);
    localStorage.setItem('cra_gemini_model', geminiModel);
    modal.classList.remove('active');
    alert('บันทึกการตั้งค่า Gemini API เรียบร้อยแล้ว!');
  });

  btnClear.addEventListener('click', () => {
    geminiApiKey = '';
    localStorage.removeItem('cra_gemini_api_key');
    inputKey.value = '';
    modal.classList.remove('active');
    alert('ล้าง Key เรียบร้อยแล้ว ระบบจะใช้ Smart Built-in Knowledge Base');
  });
}

async function callGeminiAPI(query) {
  const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/${geminiModel}:generateContent?key=${geminiApiKey}`;
  
  const systemPrompt = `คุณคือผู้ช่วยอัจฉริยะประจำหลักสูตรเภสัชศาสตรบัณฑิต (หลักสูตร ๖ ปี) (หลักสูตรใหม่ พ.ศ. ๒๕๗๑) โครงการจัดตั้งคณะเภสัชศาสตร์ ราชวิทยาลัยจุฬาภรณ์ (รจภ.)
ให้ตอบคำถามอย่างเป็นทางการ สุภาพ ถูกต้อง แม่นยำ และอ้างอิงตามข้อมูลจริงของหลักสูตร:
- จำนวนหน่วยกิต: ๑๙๕ หน่วยกิต
- สถาบันพี่เลี้ยง: คณะเภสัชศาสตร์ มหาวิทยาลัยมหิดล
- จุดเด่น: ยาชีววัตถุ, วัคซีน, ATMPs (Cell & Gene Therapy), เภสัชศาสตร์แม่นยำ (Precision Pharmacy), AI in Healthcare, เภสัชภัณฑ์รังสี (โรงพยาบาลจุฬาภรณ์และศูนย์ไซโคลตรอน)
- การฝึกงาน ๒,๐๐๐ ชั่วโมง (ปี ๕ เทอม ๒ = ๓๐๐ ชม., ปี ๖ ทั้งปี = ๑,๗๐๐ ชม.)
- อาจารย์ผู้รับผิดชอบหลักสูตร ๕ ท่าน (รศ.ดร.จุฑามณี, ศ.ดร.ไพบูลย์, รศ.ดร.นริศา, อ.ดร.พิรุณรัตน์, อ.ดร.ปัฐวิกา)
- แผนรับนักศึกษา: ปี ๒๕๗๑ เริ่มรับ ๓๐ คน
ตอบเป็นภาษาไทยในรูปแบบ HTML format ที่สวยงาม (ใช้ <p>, <ul>, <li>, <strong> ได้)`;

  const payload = {
    contents: [
      { role: 'user', parts: [{ text: `${systemPrompt}\n\nคำถามของผู้ใช้: ${query}` }] }
    ]
  };

  const resp = await fetch(endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  if (!resp.ok) {
    throw new Error(`Gemini API error: ${resp.status}`);
  }

  const data = await resp.json();
  const text = data.candidates?.[0]?.content?.parts?.[0]?.text;
  return text || 'ไม่สามารถรับข้อความตอบกลับจาก Gemini API ได้';
}

// Utilities
function escapeHtml(str) {
  return str.replace(/[&<>'"]/g, tag => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    "'": '&#39;',
    '"': '&quot;'
  }[tag] || tag));
}

function buildSearchIndex() {
  return COURSES_CATALOG.map(c => ({
    code: c.code_th,
    name: c.name_th,
    keywords: `${c.code_th} ${c.name_th} ${c.name_en} ${c.desc_th}`.toLowerCase()
  }));
}
